import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.C7GIOALF.js";const p=JSON.parse('{"title":"Using the Rules","description":"","frontmatter":{},"headers":[],"relativePath":"rules/index.md","filePath":"rules/index.md","lastUpdated":null}'),i={name:"rules/index.md"};function n(o,e,l,c,d,u){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="using-the-rules" tabindex="-1">Using the Rules <a class="header-anchor" href="#using-the-rules" aria-label="Permalink to &quot;Using the Rules&quot;">​</a></h1><h2 id="pick-a-specific-version" tabindex="-1">Pick a specific version <a class="header-anchor" href="#pick-a-specific-version" aria-label="Permalink to &quot;Pick a specific version&quot;">​</a></h2><p>A format&#39;s parent page is a directory, not a substitute for its rules. Follow a ruleset link to find the materials, deck requirements, setup, turn procedure, restrictions, and victory conditions for that version.</p><p>Use one version for a game. For example, Classic Horde&#39;s random choices and HordeMagic.com&#39;s best-interest choices are different rules; neither automatically carries over to the other.</p><h2 id="what-the-pages-cover" tabindex="-1">What the pages cover <a class="header-anchor" href="#what-the-pages-cover" aria-label="Permalink to &quot;What the pages cover&quot;">​</a></h2><p>Rules pages record the format-specific procedures. They assume players know normal Magic: casting spells, priority, the stack, combat, and card text. The <a href="https://magic.wizards.com/en/rules" target="_blank" rel="noreferrer">official Magic rules</a> remain the reference for those underlying systems.</p><p>When a page uses Commander, normal Commander deck construction, the command zone, commander tax, and commander damage still apply unless that page explicitly changes them. <a href="https://magic.wizards.com/en/formats/commander" target="_blank" rel="noreferrer">Wizards&#39; Commander rules</a> describe that base format.</p><p>Normal multiplayer setup includes an opening hand of seven and a first mulligan without reducing the final hand size. Use the current London mulligan: shuffle the hand back, draw seven, and when keeping, put one card on the bottom for each mulligan after the free first mulligan. In multiplayer games, the starting player normally draws on their first turn. A specific format rule or card may change these instructions.</p><h2 id="boxed-set-rules" tabindex="-1">Boxed-set rules <a class="header-anchor" href="#boxed-set-rules" aria-label="Permalink to &quot;Boxed-set rules&quot;">​</a></h2><p>Read the box&#39;s named base ruleset first, then its additions and replacements. A box must identify:</p><ol><li>The specific base version it uses.</li><li>Its decks and other required components.</li><li>Any replacement setup, turn, or victory rule, written out in full.</li><li>Additional rules and the exact timing of their effects.</li><li>Optional modules, with an explicit decision about which are active.</li></ol><p>Unchanged rules continue to come from the named base version. A box that has not chosen its base or victory conditions is still a draft.</p><h2 id="reading-page-status" tabindex="-1">Reading page status <a class="header-anchor" href="#reading-page-status" aria-label="Permalink to &quot;Reading page status&quot;">​</a></h2><ul><li><strong>Rules:</strong> the identified version&#39;s procedures. Any source ambiguity is stated where it matters.</li><li><strong>Local rules:</strong> the owner&#39;s house format. Existing rules are preserved; unresolved interactions are listed for a future design decision.</li><li><strong>Draft:</strong> the concept does not yet define enough rules to run without making additional choices.</li></ul><p>An open question is not a new house rule. Examples explain recorded rules; they do not silently change them. Optional rules only apply when the group chooses them before play.</p><h2 id="sources-and-card-rulings" tabindex="-1">Sources and card rulings <a class="header-anchor" href="#sources-and-card-rulings" aria-label="Permalink to &quot;Sources and card rulings&quot;">​</a></h2><p>Rules pages link to their original references and the catalogue&#39;s <a href="./../sources/">source notes</a>. Source notes may contain historical commentary, proposals, or different versions; they are not automatically additional rules for every game.</p><p>Use current Oracle text for official cards. Custom identities and other fan-made cards use their own published text. Card rulings do not, by themselves, decide an unfinished house-format rule.</p>',18)])])}const m=a(i,[["render",n]]);export{p as __pageData,m as default};
